/bin/bash -lc "python3 - <<'PY'
import requests
for repo in ['scipy','scipy-base','python']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=10'
    try:
        r=requests.get(url, timeout=20)
        print('repo', repo, 'status', r.status_code)
        if r.ok:
            tags=[t.get('name') for t in r.json().get('tags', [])[:10]]
            print(tags)
    except Exception as e:
        print('repo', repo, 'error', type(e).__name__, str(e))
PY"

